us":"Available","source_updated_at":"2025-09-03T22:27:54+00:00","title":"Finchley Road, London NW11","summary":"Prominent North West London Showroom/Gym/Mini Supermarket Premises with Large Window Frontages onto Busy High Road","address_line":"Finchley Road, London NW11","area":null,"city":"London","postcode":"NW11 8DL","lat":51.564221,"lng":-0.197002,"property_type":"Other Leisure","use_class":null,"disposal_type":"new_lease","to_let":true,"for_sale":false,"rent_pa":null,"rent_raw":null,"rent_period":null,"premium":null,"premium_raw":null,"guide_price":null,"price_qualifier":"on_application","vat_applicable":null,"rateable_value":null,"business_rates":null,"service_charge":null,"estate_charge":null,"parking_charge":null,"tenure_raw":"New Sub Lease availbale from my clients 999 year Head Lease","lease_term_years":null,"lease_expiry":null,"rent_review_basis":null,"next_rent_review":null,"inside_1954_act":null,"size_sqft":4674,"size_sqm":434.23,"covers_internal":null,"covers_external":null,"floors":[{"name":"Ground","sqft":4674,"sqm":434.23}],"licensing_notes":null,"fit_out_state":null,"epc_rating":null,"description":"The premises benefit from a huge window frontage on a corner therefore benefitting from a good return frontage as well. Currently trading as a Showroom laid out over ground floor only in mainly opne plan space with good ceiling height. The premises lend themselves for a variety of users such as Gyms / Mini Supermarket / Showroom / Studio type operators.","location_description":"The premises are ideally located on the busy Finchley Road in North West London in the affluent location of Hampstead Garden Suburb.","key_features":["Prominent Corner Premises","Affluent Location","Open Plan Ground Floor","Good Ceiling Height","New Sub Lease"],"sections":[{"title":"Description","content":"The premises benefit from a huge window frontage on a corner therefore benefitting from a good return frontage as well. Currently trading as a Showroom laid out over ground floor only in mainly opne plan space with good ceiling height. The premises lend themselves for a variety of users such as Gyms / Mini Supermarket / Showroom / Studio type operators."},{"title":"Tenure","content":"New Sub Lease availbale from my clients 999 year Head Lease"},{"title":"Rent","content":"Rent Upon Application"},{"title":"Holding Deposit","content":"Upon agreement of a transaction we would request a holding deposit to be paid to CDG Leisure client account released upon completion of a transaction."},{"title":"Confidentiality","content":"These premises are confidential - pls enquire within for full info and under no Circumstance is anyone to approach staff about this opportunity"}],"agent_name":"Morris Greenberg","agent_email":"morris@cdgleisure.com","agent_phone":"0207 100 5520","agent_photo":"https://as-images.imgix.net/600c00648e2a5fd30d8e13c5f877c55b-mo%20pic.jpg","images":[{"url":"https://as-images.imgix.net/0fa984e130a483bd4217598c0fa6d327-emptyinteriorsupermarketgrocerystorewithnopeople-641503102434.jpg","alt":"Finchley Road, London NW11, London, Other Leisure To Let - emptyinteriorsupermarketgrocerystorewithnopeople_641503102434.jpg","source_url":"https://as-images.imgix.net/0fa984e130a483bd4217598c0fa6d327-emptyinteriorsupermarketgrocerystorewithnopeople-641503102434.jpg?mark=https%3A%2F%2Fas-images.imgix.net%2F5fcc3b7220158f27f85989bfa2708db8-screenshot-2024-06-19-at-14-54-05-removebg-preview.png&mark-alpha=90&mark-scale=30&mark-align=right,bottom"}],"brochure_url":"https://s3-eu-west-1.amazonaws.com/agents-society-assets-files/pdf/96e0daee7820ce7d8827c5158bd75e32.pdf"}]$cdg$::jsonb;
begin
  select id into demo_agency from public.agencies where name = 'CDG demo' limit 1;
  if demo_agency is null then raise exception 'Demo agency "CDG demo" not found.'; end if;

  select array_agg(user_id order by user_id) into member_ids
    from public.agency_members where agency_id = demo_agency;
  if member_ids is null or array_length(member_ids, 1) = 0 then
    raise exception 'Demo agency has no members.';
  end if;

  for rec in select * from jsonb_array_elements(payload) loop
    i := i + 1;
    select p.id into lead
      from public.profiles p
      join public.agency_members am on am.user_id = p.id
     where am.agency_id = demo_agency and p.full_name = rec->>'agent_name'
     limit 1;
    if lead is null then lead := member_ids[1 + (i % array_length(member_ids, 1))]; end if;
    insert into public.disposals (
      agency_id, source, source_ref, source_url, status, source_updated_at,
      title, summary, address_line, area, city, postcode, lat, lng,
      property_type, use_class, disposal_type, to_let, for_sale,
      rent_pa, rent_raw, rent_period, premium, premium_raw, guide_price, price_qualifier,
      vat_applicable, rateable_value, business_rates, service_charge, estate_charge, parking_charge,
      tenure_raw, lease_term_years, lease_expiry, rent_review_basis, next_rent_review, inside_1954_act,
      size_sqft, size_sqm, covers_internal, covers_external, floors,
      licensing_notes, fit_out_state, epc_rating,
      description, location_description, key_features, sections,
      agent_name, agent_email, agent_phone, agent_photo,
      images, brochure_url,
      lead_agent_id, created_by
    ) values (
      demo_agency,
      coalesce(rec->>'source', 'cdg'), rec->>'source_ref', rec->>'source_url', rec->>'status',
      (rec->>'source_updated_at')::timestamptz,
      rec->>'title', rec->>'summary', rec->>'address_line', rec->>'area', rec->>'city',
      rec->>'postcode', (rec->>'lat')::double precision, (rec->>'lng')::double precision,
      rec->>'property_type', rec->>'use_class', rec->>'disposal_type',
      (rec->>'to_let')::boolean, (rec->>'for_sale')::boolean,
      (rec->>'rent_pa')::numeric, rec->>'rent_raw', rec->>'rent_period',
      (rec->>'premium')::numeric, rec->>'premium_raw', (rec->>'guide_price')::numeric,
      rec->>'price_qualifier',
      (rec->>'vat_applicable')::boolean, (rec->>'rateable_value')::numeric,
      (rec->>'business_rates')::numeric, (rec->>'service_charge')::numeric,
      (rec->>'estate_charge')::numeric, (rec->>'parking_charge')::numeric,
      rec->>'tenure_raw', (rec->>'lease_term_years')::int, (rec->>'lease_expiry')::date,
      rec->>'rent_review_basis', (rec->>'next_rent_review')::int, (rec->>'inside_1954_act')::boolean,
      (rec->>'size_sqft')::numeric, (rec->>'size_sqm')::numeric,
      (rec->>'covers_internal')::int, (rec->>'covers_external')::int,
      coalesce(rec->'floors', '[]'::jsonb),
      rec->>'licensing_notes', rec->>'fit_out_state', rec->>'epc_rating',
      rec->>'description', rec->>'location_description',
      coalesce(array(select jsonb_array_elements_text(rec->'key_features')), '{}'::text[]),
      coalesce(rec->'sections', '[]'::jsonb),
      rec->>'agent_name', rec->>'agent_email', rec->>'agent_phone', rec->>'agent_photo',
      coalesce(rec->'images', '[]'::jsonb), rec->>'brochure_url',
      lead, lead
    );
  end loop;
end $$;
